Auth::start();ob_start();$_SERVER['HTTP_USER_AGENT']='RoofProductionTest';$db=Database::getInstance()->connection();$fail=[];$ids=[];
function rpq($db,$sql,$p=[]){$s=$db->prepare($sql);$s->execute($p);return$s;}function rpok($c,$m){global$fail;echo($c?'OK  - ':'FAIL - ').$m."\n";if(!$c)$fail[]=$m;}
try{$users=rpq($db,"SELECT u.*,r.name role_name,r.slug role_slug FROM users u JOIN roles r ON r.id=u.role_id WHERE u.status='active' AND u.deleted_at IS NULL AND r.slug IN('administrateur','direction') LIMIT 2")->fetchAll();if(count($users)<2)throw new RuntimeException('Deux utilisateurs requis.');$creator=$users[0];$validator=$users[1];$mino=(int)rpq($db,"SELECT id FROM sites WHERE code='MINO'")->fetchColumn();$siloSite=(int)rpq($db,"SELECT id FROM sites WHERE code='SILO'")->fetchColumn();$corn=(int)rpq($db,"SELECT id FROM products WHERE code='MAIS-BRUT'")->fetchColumn();$machine=(int)rpq($db,"SELECT id FROM machines WHERE code='ROOF-1'")->fetchColumn();
 Auth::login($creator);Auth::selectSite((string)$mino);$creator=Auth::user();$code='TST-ROOF-'.random_int(1000,9999);rpq($db,"INSERT INTO silos(site_id,name,code,product_id,capacity_kg,current_stock_kg,status) VALUES(?,? ,?, ?,5000,3000,'active')",[$siloSite,'Silo test ROOF',$code,$corn]);$ids['silo']=(int)$db->lastInsertId();$feed=(new MachineFeed())->createFeed(['silo_id'=>$ids['silo'],'machine_id'=>$machine,'authorized_quantity_kg'=>1100,'quantity_kg'=>1000,'fed_at'=>date('Y-m-d H:i:s'),'ended_at'=>'','observation'=>'Test ROOF'],$creator);$ids['feed']=$feed;$ids['batch']=(int)rpq($db,'SELECT id FROM production_batches WHERE machine_feed_id=?',[$feed])->fetchColumn();$ids['movement']=(int)rpq($db,'SELECT silo_movement_id FROM machine_feeds WHERE id=?',[$feed])->fetchColumn();rpok((int)rpq($db,"SELECT COUNT(*) FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code='BSS' AND d.id=(SELECT bss_document_id FROM machine_feeds WHERE id=?)",[$feed])->fetchColumn()===1,'BSS validé avant alimentation et lié au lot');rpok((float)rpq($db,'SELECT current_stock_kg FROM silos WHERE id=?',[$ids['silo']])->fetchColumn()===2000.0,'Stock silo diminué du maïs réellement chargé');
 $model=new ProductionBatch();$types=$model->wasteTypes();$waste=[$types[0]['id']=>100,$types[1]['id']=>50];$data=['production_batch_id'=>$ids['batch'],'output_quantity_kg'=>800,'waste_lines'=>$waste,'variance_tolerance_percent'=>2,'variance_justification'=>'','ended_at'=>date('Y-m-d H:i:s')];try{$model->submitResults($data,$creator);$blocked=false;}catch(Exception$e){$blocked=true;}rpok($blocked,'Dépassement de tolérance refusé sans justification');$data['variance_justification']='Perte documentée au nettoyage';$status=$model->submitResults($data,$creator);rpok($status==='pending_additional_approval','Écart hors tolérance envoyé en approbation complémentaire');$b=$model->findDetailed($ids['batch']);rpok(abs((float)$b['yield_percent']-80)<.001&&abs((float)$b['variance_quantity_kg']-50)<.001&&abs((float)$b['variance_percent']-5)<.001,'Rendement, écart et pourcentage calculés sans égalité forcée');
 try{$model->validateProduction(['production_batch_id'=>$ids['batch']],$creator);$blocked=false;}catch(Exception$e){$blocked=true;}rpok($blocked,'Créateur empêché de valider son lot');Auth::login($validator);Auth::selectSite((string)$mino);$validator=Auth::user();$model->validateProduction(['production_batch_id'=>$ids['batch']],$validator);rpok((float)rpq($db,'SELECT quantity_kg FROM bulk_flour_stocks WHERE production_batch_id=?',[$ids['batch']])->fetchColumn()===800.0,'Farine non emballée disponible par lot');rpok((float)rpq($db,'SELECT SUM(quantity_kg) FROM waste_stocks WHERE production_batch_id=?',[$ids['batch']])->fetchColumn()===150.0,'Déchets disponibles simultanément par type et lot');try{$model->validateProduction(['production_batch_id'=>$ids['batch']],$validator);$blocked=false;}catch(Exception$e){$blocked=true;}rpok($blocked,'Double validation refusée');
}catch(Exception$e){echo'ERREUR - '.$e->getMessage()."\n";$fail[]=$e->getMessage();}finally{if(!empty($ids['feed'])){rpq($db,'UPDATE machine_feeds SET bss_document_id=NULL WHERE id=?',[$ids['feed']]);}$entities=['production_batches'=>$ids['batch']??0,'silo_movements'=>$ids['movement']??0];foreach($entities as$type=>$id){if(!$id)continue;$docs=rpq($db,'SELECT id FROM documents WHERE entity_type=? AND entity_id=?',[$type,$id])->fetchAll(PDO::FETCH_COLUMN);foreach($docs as$doc){$wf=rpq($db,'SELECT id FROM workflow_instances WHERE document_id=?',[$doc])->fetchAll(PDO::FETCH_COLUMN);foreach($wf as$w){foreach(['workflow_notifications','workflow_level_approvals','workflow_transitions']as$t)rpq($db,"DELETE FROM $t WHERE workflow_instance_id=?",[$w]);rpq($db,'DELETE FROM workflow_instances WHERE id=?',[$w]);}rpq($db,'DELETE FROM document_status_history WHERE document_id=?',[$doc]);rpq($db,'DELETE FROM documents WHERE id=?',[$doc]);}}if(!empty($ids['batch'])){rpq($db,'DELETE FROM bulk_flour_stocks WHERE production_batch_id=?',[$ids['batch']]);rpq($db,'DELETE FROM waste_stocks WHERE production_batch_id=?',[$ids['batch']]);rpq($db,'DELETE FROM production_waste_lines WHERE production_batch_id=?',[$ids['batch']]);rpq($db,'DELETE FROM production_batches WHERE id=?',[$ids['batch']]);}if(!empty($ids['feed']))rpq($db,'DELETE FROM machine_feeds WHERE id=?',[$ids['feed']]);if(!empty($ids['movement']))rpq($db,'DELETE FROM silo_movements WHERE id=?',[$ids['movement']]);if(!empty($ids['silo']))rpq($db,'DELETE FROM silos WHERE id=?',[$ids['silo']]);rpq($db,"DELETE FROM activity_logs WHERE user_agent='RoofProductionTest'");}ob_end_flush();if($fail)exit(1);echo"\nProduction ROOF conforme.\n";
